// Plain-main C++20 tests for the FP64 reference port.
// Build: g++ -std=c++20 -O2 -Wall -Wextra test_reference.cpp -o test_reference
// Run:   ./test_reference
//
// Loads ../testdata/*.tile generated by generate_testdata.py (Python ref).

#include "neural_reference.hpp"

#include <algorithm>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <limits>
#include <sstream>
#include <string>
#include <vector>

namespace fs = std::filesystem;
using nbref::Source;
using nbref::Vec3;

namespace
{
    int checks = 0;
    int failures = 0;

    void check(bool ok, std::string const& what)
    {
        ++checks;
        if(!ok)
        {
            ++failures;
            std::cerr << "FAIL: " << what << "\n";
        }
    }

    struct Case
    {
        std::string name;
        double dx = 1.0, dy = 1.0, dz = 1.0;
        Vec3 x_tile{};
        std::vector<Source> sources;
        nbref::Settings settings{};
        std::vector<double> tile;
    };

    Case load_case(fs::path const& path)
    {
        std::ifstream in(path);
        if(!in)
            throw std::runtime_error("cannot open " + path.string());
        Case c;
        std::string token;
        while(in >> token)
        {
            if(token == "name")
                in >> c.name;
            else if(token == "dx")
                in >> c.dx >> c.dy >> c.dz;
            else if(token == "x_tile")
                in >> c.x_tile.x >> c.x_tile.y >> c.x_tile.z;
            else if(token == "nsrc")
            {
                int n = 0;
                in >> n;
                c.sources.resize(n);
                for(Source& s : c.sources)
                {
                    std::string tag;
                    in >> tag;
                    if(tag != "src")
                        throw std::runtime_error("expected src in " + path.string());
                    in >> s.x.x >> s.x.y >> s.x.z >> s.u.x >> s.u.y >> s.u.z >> s.w;
                }
            }
            else if(token == "order")
                in >> c.settings.order;
            else if(token == "tol")
                in >> c.settings.tol;
            else if(token == "max_level")
                in >> c.settings.max_level;
            else if(token == "max_order")
                in >> c.settings.max_order;
            else if(token == "near_order")
            {
                int ignored = 0;
                in >> ignored;
            }
            else if(token == "tile")
            {
                c.tile.resize(1536);
                for(double& v : c.tile)
                    in >> v;
                break;
            }
            else
                throw std::runtime_error("unknown token '" + token + "' in " + path.string());
        }
        if(c.tile.size() != 1536)
            throw std::runtime_error("short tile in " + path.string());
        return c;
    }

    bool is_near_case(std::string const& name)
    {
        return name.find("near") != std::string::npos;
    }

    void test_golden_cases(fs::path const& dir)
    {
        std::vector<fs::path> paths;
        for(auto const& entry : fs::directory_iterator(dir))
            if(entry.path().extension() == ".tile")
                paths.push_back(entry.path());
        std::sort(paths.begin(), paths.end());
        check(!paths.empty(), "golden testdata present");

        for(auto const& path : paths)
        {
            Case c = load_case(path);
            nbref::TileReport report;
            auto got = nbref::tile_field(
                c.x_tile, c.sources, c.dx, c.dy, c.dz, c.settings, &report);
            check(got.size() == 1536, c.name + ": tile size");

            double max_abs = 0.0;
            double max_ref = 0.0;
            bool finite = true;
            for(std::size_t i = 0; i < got.size(); ++i)
            {
                finite = finite && std::isfinite(got[i]);
                max_abs = std::max(max_abs, std::abs(got[i] - c.tile[i]));
                max_ref = std::max(max_ref, std::abs(c.tile[i]));
            }
            double const rel = max_abs / std::max(max_ref, 1e-300);
            double const limit = is_near_case(c.name) ? 1e-7 : 1e-10;

            std::cout << "golden " << c.name << ": rel_inf=" << rel
                      << " limit=" << limit
                      << " near=" << (report.any_near ? "yes" : "no")
                      << " max_quad_err=" << report.max_error << "\n";
            check(finite, c.name + ": finite");
            check(rel <= limit, c.name + ": relative error limit");
            check(!report.any_near || report.all_converged, c.name + ": converged");

            if(c.name == "far_iso_gamma1_stationary")
            {
                // Exact zero B channels for a stationary source.
                bool b_zero = true;
                for(int k = 0; k < 4; ++k)
                    for(int j = 0; j < 8; ++j)
                        for(int i = 0; i < 8; ++i)
                            for(int cc = 3; cc < 6; ++cc)
                                b_zero = b_zero
                                    && got[cc + 6 * (i + 8 * (j + 8 * k))] == 0.0;
                check(b_zero, "stationary: B exactly zero");
            }
        }
    }

    void test_aspect_cases(fs::path const& dir)
    {
        std::ifstream in(dir / "aspect_cases.txt");
        check(static_cast<bool>(in), "aspect_cases.txt present");
        if(!in)
            return;

        nbref::Settings s4;
        nbref::Settings s6;
        nbref::Settings s8;
        s6.order = 6;
        s8.order = 8;
        nbref::Settings s;
        std::string line;
        double worst_py = 0.0;
        double worst_order = 0.0;
        int cases = 0;
        while(std::getline(in, line))
        {
            if(line.empty() || line[0] == '#')
                continue;
            std::istringstream ss(line);
            double v[15];
            for(double& x : v)
                ss >> x;
            Vec3 const cells{v[0], v[1], v[2]};
            Vec3 const R0{v[3], v[4], v[5]};
            Vec3 const u{v[6], v[7], v[8]};
            Vec3 const Eref{v[9], v[10], v[11]};
            Vec3 const Bref{v[12], v[13], v[14]};

            Vec3 E4, B4, E6, B6, E8, B8;
            nbref::shape_field(R0, Vec3{}, u, cells.x, cells.y, cells.z, s4, E4, B4);
            nbref::shape_field(R0, Vec3{}, u, cells.x, cells.y, cells.z, s6, E6, B6);
            nbref::shape_field(R0, Vec3{}, u, cells.x, cells.y, cells.z, s8, E8, B8);

            double max_ref = 0.0;
            for(int i = 0; i < 3; ++i)
            {
                max_ref = std::max(max_ref, std::abs(Eref[i]));
                max_ref = std::max(max_ref, std::abs(Bref[i]));
            }
            double max_py = 0.0;
            for(int i = 0; i < 3; ++i)
            {
                max_py = std::max(max_py, std::abs(E4[i] - Eref[i]));
                max_py = std::max(max_py, std::abs(B4[i] - Bref[i]));
            }
            double max_ord = 0.0;
            for(int i = 0; i < 3; ++i)
            {
                max_ord = std::max(max_ord, std::abs(E4[i] - E8[i]));
                max_ord = std::max(max_ord, std::abs(E6[i] - E8[i]));
                max_ord = std::max(max_ord, std::abs(B4[i] - B8[i]));
                max_ord = std::max(max_ord, std::abs(B6[i] - B8[i]));
            }
            double const rel_py = max_ref > 0.0
                ? max_py / max_ref
                : (max_py == 0.0 ? 0.0 : std::numeric_limits<double>::infinity());
            double const rel_ord = max_ref > 0.0
                ? max_ord / max_ref
                : (max_ord == 0.0 ? 0.0 : std::numeric_limits<double>::infinity());
            worst_py = std::max(worst_py, rel_py);
            worst_order = std::max(worst_order, rel_ord);
            ++cases;
            check(rel_py <= 1e-9, "aspect case Python/C++ agreement");
            check(rel_ord <= 1e-6, "aspect case order 4/6/8 agreement");
        }
        std::cout << "aspect grid: " << cases
                  << " cases, worst Python/C++=" << worst_py
                  << ", worst order4/6/8=" << worst_order << "\n";
        check(cases == 225, "aspect grid case count");
    }

    void test_near_cases(fs::path const& dir)
    {
        std::ifstream in(dir / "near_cases.txt");
        check(static_cast<bool>(in), "near_cases.txt present");
        if(!in)
            return;
        nbref::Settings s;
        std::string line;
        double worst = 0.0;
        int cases = 0;
        while(std::getline(in, line))
        {
            if(line.empty() || line[0] == '#')
                continue;
            std::istringstream ss(line);
            double v[15];
            for(double& x : v)
                ss >> x;
            Vec3 const cells{v[0], v[1], v[2]};
            Vec3 const R0{v[3], v[4], v[5]};
            Vec3 const u{v[6], v[7], v[8]};
            Vec3 const Eref{v[9], v[10], v[11]};
            Vec3 const Bref{v[12], v[13], v[14]};
            Vec3 E, B;
            nbref::shape_field(
                R0, Vec3{}, u, cells.x, cells.y, cells.z, s, E, B);
            double max_ref = 0.0, max_diff = 0.0;
            for(int i = 0; i < 3; ++i)
            {
                max_ref = std::max({max_ref, std::abs(Eref[i]), std::abs(Bref[i])});
                max_diff = std::max({max_diff, std::abs(E[i] - Eref[i]),
                                     std::abs(B[i] - Bref[i])});
            }
            double const rel = max_ref > 0.0
                ? max_diff / max_ref
                : (max_diff == 0.0 ? 0.0 : std::numeric_limits<double>::infinity());
            worst = std::max(worst, rel);
            ++cases;
            check(rel <= 1e-9, "near set Python/C++ agreement");
        }
        std::cout << "near test set: " << cases
                  << " cases, worst Python/C++=" << worst << "\n";
        check(cases == 24, "near set case count");
    }

    void test_zero_sources()
    {
        nbref::Settings s;
        auto empty = nbref::tile_field(Vec3{}, {}, 1.0, 1.0, 1.0, s);
        bool all_zero = std::all_of(empty.begin(), empty.end(), [](double v) {
            return v == 0.0;
        });
        check(all_zero, "empty sources: exact zero tile");

        std::vector<Source> zero_weight{{Vec3{0.2, -0.1, 0.3}, Vec3{0.4, 0.0, 0.0}, 0.0}};
        auto zw = nbref::tile_field(Vec3{}, zero_weight, 1.0, 1.0, 1.0, s);
        all_zero = std::all_of(zw.begin(), zw.end(), [](double v) {
            return v == 0.0;
        });
        check(all_zero, "zero weight: exact zero tile");
    }

    void test_offsets_flatten_and_direct()
    {
        auto const& off = nbref::offsets();
        std::array<Vec3, 6> const expected{{
            {0.5, 0.0, 0.0},
            {0.0, 0.5, 0.0},
            {0.0, 0.0, 0.5},
            {0.0, 0.5, 0.5},
            {0.5, 0.0, 0.5},
            {0.5, 0.5, 0.0},
        }};
        bool offsets_ok = true;
        for(int c = 0; c < 6; ++c)
            offsets_ok = offsets_ok
                && off[c].x == expected[c].x
                && off[c].y == expected[c].y
                && off[c].z == expected[c].z;
        check(offsets_ok, "six Yee offsets pinned");

        Vec3 const x_tile{0.3, -0.7, 1.1};
        double const dx = 0.8, dy = 1.1, dz = 0.6;
        Vec3 const cells{dx, dy, dz};
        Vec3 const x_src{
            x_tile.x - 32.0 * dx,
            x_tile.y + 0.25 * dy,
            x_tile.z - 0.35 * dz};
        Vec3 const u{0.4, -0.2, 0.1};
        double const w = 1.7;
        nbref::Settings s;
        s.order = 6;
        auto tile = nbref::tile_field(x_tile, {{x_src, u, w}}, dx, dy, dz, s);

        double max_abs = 0.0;
        double max_ref = 0.0;
        for(int k = 0; k < 4; ++k)
            for(int j = 0; j < 8; ++j)
                for(int i = 0; i < 8; ++i)
                    for(int c = 0; c < 6; ++c)
                    {
                        Vec3 const pos = x_tile
                            + Vec3{
                                (i + expected[c].x) * cells.x,
                                (j + expected[c].y) * cells.y,
                                (k + expected[c].z) * cells.z};
                        Vec3 E, B;
                        nbref::shape_field(pos, x_src, u, dx, dy, dz, s, E, B);
                        double const component = c < 3 ? E[c] : B[c - 3];
                        double const want = -w * dx * dx * component;
                        double const got = tile[c + 6 * (i + 8 * (j + 8 * k))];
                        max_abs = std::max(max_abs, std::abs(got - want));
                        max_ref = std::max(max_ref, std::abs(want));
                    }
        double const rel = max_abs / std::max(max_ref, 1e-300);
        std::cout << "all-slot direct check: rel_inf=" << rel << "\n";
        check(rel <= 1e-12, "all 1536 slots/offsets/flatten order");
    }

    void test_translation_invariance()
    {
        nbref::Settings s;
        s.order = 6;
        Vec3 const u{0.2, 0.3, -0.1};
        Vec3 const src{0.5, -0.5, 0.8};
        Vec3 const shift{7.0, -3.0, 2.0};
        auto a = nbref::tile_field(Vec3{}, {{src, u, 1.3}}, 1.0, 1.0, 1.0, s);
        auto b = nbref::tile_field(shift, {{src + shift, u, 1.3}}, 1.0, 1.0, 1.0, s);
        double max_abs = 0.0, max_ref = 0.0;
        for(std::size_t i = 0; i < a.size(); ++i)
        {
            max_abs = std::max(max_abs, std::abs(a[i] - b[i]));
            max_ref = std::max(max_ref, std::abs(a[i]));
        }
        double const rel = max_abs / std::max(max_ref, 1e-300);
        std::cout << "translation invariance: rel_inf=" << rel << "\n";
        check(rel <= 1e-12, "translation invariance");
    }

    void test_inverse_square_scaling()
    {
        nbref::Settings s;
        s.order = 6;
        Vec3 const u{0.1, 0.2, 0.3};
        Vec3 const R{4.0, 1.0, -2.0};
        double const lambda = 3.0;
        Vec3 E1, B1, E2, B2;
        nbref::shape_field(R, Vec3{}, u, 1.0, 1.0, 1.0, s, E1, B1);
        nbref::shape_field(
            R * lambda, Vec3{}, u, lambda, lambda, lambda, s, E2, B2);
        double max_e = 0.0, max_b = 0.0, ref_e = 0.0, ref_b = 0.0;
        for(int i = 0; i < 3; ++i)
        {
            double const want_e = E1[i] / (lambda * lambda);
            double const want_b = B1[i] / (lambda * lambda);
            max_e = std::max(max_e, std::abs(E2[i] - want_e));
            max_b = std::max(max_b, std::abs(B2[i] - want_b));
            ref_e = std::max(ref_e, std::abs(want_e));
            ref_b = std::max(ref_b, std::abs(want_b));
        }
        double const rel = std::max(
            max_e / std::max(ref_e, 1e-300),
            max_b / std::max(ref_b, 1e-300));
        std::cout << "E ~ 1/L^2 scaling: rel_inf=" << rel << "\n";
        check(rel <= 1e-12, "E and B scale as 1/L^2");
    }

    void test_point_gamma_stability()
    {
        nbref::Settings s;
        for(double gamma : {1.0, 2.0, 10.0, 100.0})
        {
            double const p = gamma == 1.0 ? 0.0 : std::sqrt(gamma * gamma - 1.0);
            Vec3 E, B;
            nbref::point_field(Vec3{0.0, 1.0, 1.0}, Vec3{p, 0.0, 0.0}, E, B);
            bool const finite = std::isfinite(E.x) && std::isfinite(E.y)
                && std::isfinite(E.z) && std::isfinite(B.x) && std::isfinite(B.y)
                && std::isfinite(B.z);
            check(finite, "point_field finite at gamma " + std::to_string(gamma));
        }
        Vec3 E, B;
        nbref::point_field(Vec3{1.0, -2.0, 3.0}, Vec3{}, E, B);
        check(B.x == 0.0 && B.y == 0.0 && B.z == 0.0, "static point B exactly zero");
    }
} // namespace

int main(int argc, char** argv)
{
    fs::path dir = "testdata";
    if(argc > 1)
        dir = argv[1];
    try
    {
        test_golden_cases(dir);
        test_aspect_cases(dir);
        test_near_cases(dir);
        test_zero_sources();
        test_offsets_flatten_and_direct();
        test_translation_invariance();
        test_inverse_square_scaling();
        test_point_gamma_stability();
    }
    catch(std::exception const& e)
    {
        std::cerr << "ERROR: " << e.what() << "\n";
        return 2;
    }
    std::cout << "\n" << checks << " checks, " << failures << " failures\n";
    return failures == 0 ? 0 : 1;
}
